void toggleIsInterNetAvailable(bool isInternetAvailable) {
  if (!isInternetAvailable) {
    if (cubit.isEditMode) {
      cubit.exitFromEditMode();
    }
    if (context.mounted &&
        cubit.watchlistList.isNotEmpty &&
        cubit.shouldShowToast) {
      showNoInternetToast();
    } else {
      hideErrorSnackBar();
    }
  } else {
    _loadData(localSelectedWatchlistId);
    hideErrorSnackBar();
  }
  super.toggleIsInterNetAvailable(isInternetAvailable);
}

