void stopNetworkStreaming() {
  subscription?.cancel();
}

void startNetworkStreaming() async {
  // Use unified ConnectivityManager to prevent TooManyRequestsException
  final connectivityResult = await ConnectivityManager.instance.getConnectivityResult();
  //Todo need to check
  latConnectedType ??= ConnectivityResultExtension(connectivityResult.last).network;
  subscription = subscription ??
      AppEventStreamImpl.getInstance()
          .network
          .startWith(ConnectivityResultExtension(connectivityResult.last).network)
          .listen((event) {
        debugPrint("The internet is available $event");
        if (!event.isConnected) {
          checkConnectivityWithDelay();
        }
        _handleNetworkEvent(event);
      });
}

after_code.code:
void stopNetworkStreaming() {
  subscription?.cancel();
  if (StreamingFlags.restartNetworkListener) {
    subscription = null; // allow startNetworkStreaming to listen again
  }
}
